rep('function normalizeEcology(v){return{habitat:Object.assign({},DEFAULT_HABITAT,v&&v.habitat||{})}}',r'''function normalizeEcology(v){return{habitat:Object.assign({},DEFAULT_HABITAT,v&&v.habitat||{}),practice:Object.assign({},DEFAULT_PRACTICE,v&&v.practice||{},v&&v.habitat?{noPesticides:v.habitat.noPesticides!==false}: {})}}
function normalizeHabitatEntry(h){h=h||{};if(!h.id)h.id=uid();if(!h.status)h.status="present";if(typeof h.favorite!=="boolean")h.favorite=false;if(!h.created)h.created=isoToday();return h}
function normalizeAnimalObservation(a){a=a||{};if(!a.id)a.id=uid();if(!a.date)a.date=isoToday();if(!a.created)a.created=isoToday();if(!a.group)a.group="other";return a}
function migrateLegacyHabitats(oldEco){if(state.habitats.length)return;var h=oldEco&&oldEco.habitat||{},map=[["waterSource","water_station"],["deadwood","deadwood"],["bareSoil","bare_soil"],["wildCorner","wild_corner"]];map.forEach(function(x){if(h[x[0]])state.habitats.push(normalizeHabitatEntry({type:x[1],status:"present",area:"",notes:"Aus der früheren Lebensraum-Einstellung übernommen."}))})}
function nativePlantStatus(){var yes=0,no=0,unknown=0;state.plants.forEach(function(p){if(p.ecoNative==="yes"){yes++;return}if(p.ecoNative==="no"){no++;return}var r=ecoProfileFor(p);if(r&&r.nat>=10)yes++;else if(r&&r.nat<=3)no++;else unknown++});var known=yes+no,ratio=known?yes/known:0,active=known>=5&&ratio>=.60;return{yes:yes,no:no,unknown:unknown,known:known,ratio:ratio,active:active}}
function practiceScore(){var p=state.ecology&&state.ecology.practice||DEFAULT_PRACTICE,n=nativePlantStatus(),v=0;if(p.noPesticides)v+=2;if(p.leaveStemsInWinter)v+=2;if(p.leavesPartlyRemain)v+=1;if(p.peatFree)v+=1;if(p.lessFrequentMowing)v+=1;if(p.reducedNightLight)v+=1;if(n.active)v+=2;return Math.min(10,v)}
function habitatLibraryItem(type){return HABITAT_LIBRARY[type]||{title:"Lebensraum",category:"other",icon:"🌿",score:5,supports:["andere insekten"],tip:"Struktur möglichst naturnah und dauerhaft erhalten."}}
function habitatStatusFactor(v){return{idea:0,planned:.25,present:1,optimized:1.15}[v]||0}
function habitatStatusLabel(v){return{idea:"Idee",planned:"Geplant",present:"Vorhanden",optimized:"Optimiert"}[v]||"Vorhanden"}
function habitatCategoryLabel(v){return{water:"Wasser",structure:"Nistplätze & Struktur",refuge:"Rückzug & Winter",food:"Nahrung"}[v]||"Lebensraum"}
function habitatEntryImpact(h){var d=habitatLibraryItem(h.type);return Math.round(d.score*habitatStatusFactor(h.status)*10)/10}
function habitatCollectionScore(){var cats={water:0,structure:0,refuge:0,food:0},caps={water:3,structure:5,refuge:3,food:4},byType={};state.habitats.forEach(function(h){var d=habitatLibraryItem(h.type);(byType[h.type]||(byType[h.type]=[])).push(h)});Object.keys(byType).forEach(function(t){var d=habitatLibraryItem(t),arr=byType[t].slice().sort(function(a,b){return habitatStatusFactor(b.status)-habitatStatusFactor(a.status)}),raw=0;arr.forEach(function(h,i){raw+=d.score*habitatStatusFactor(h.status)*(i===0?1:i===1?.5:.25)});cats[d.category]=(cats[d.category]||0)+raw});var total=0;Object.keys(caps).forEach(function(c){total+=Math.min(caps[c],Math.round((cats[c]/10*caps[c])*10)/10)});return Math.min(15,Math.round(total))}''','normalizers')

# Replace score model
sub(r'function habitatScore\(h\)\{[^\n]*\}\nfunction gardenEcoScore\(plantsOverride\)\{[^\n]*\}',r'''function habitatScore(){return habitatCollectionScore()}
function gardenEcoScore(plantsOverride){var plants=(plantsOverride||state.plants||[]).map(normalizePlantData),unique={},families=new Set(),types=new Set();plants.forEach(function(p){var k=(p.scientific||p.name||p.id||"").trim().toLowerCase();if(!unique[k]||plantInsectValue(p).score>plantInsectValue(unique[k]).score)unique[k]=p;if(p.family)families.add(String(p.family).toLowerCase());if(p.type)types.add(p.type)});var ups=Object.keys(unique).map(function(k){return unique[k]}),quality=0;if(ups.length){var scores=ups.map(function(p){return plantInsectValue(p).score}).sort(function(a,b){return b-a}).slice(0,20);quality=Math.round((scores.reduce(function(a,b){return a+b},0)/scores.length)*.40)}var counts=Array(12).fill(0);ups.forEach(function(p){plantInsectValue(p).bloomMonths.forEach(function(m){if(m>=1&&m<=12)counts[m-1]++})});var relevant=[2,3,4,5,6,7,8,9],bloom=0,covered=true;relevant.forEach(function(i){if(counts[i]>=2)bloom+=2;else if(counts[i]>=1)bloom+=1;else covered=false});if(covered)bloom+=4;bloom=Math.min(20,bloom);var speciesPts=Math.min(7,Math.round(ups.length*.85)),familyPts=Math.min(4,Math.round(families.size*.9)),typePts=Math.min(4,Math.round(types.size*1.35)),diversity=Math.min(15,speciesPts+familyPts+typePts),hab=habitatCollectionScore(),practice=practiceScore(),total=Math.max(0,Math.min(100,quality+bloom+diversity+hab+practice)),native=nativePlantStatus();return{total:total,quality:quality,bloom:bloom,diversity:diversity,habitat:hab,practice:practice,counts:counts,uniqueCount:ups.length,valuable:plants.filter(function(p){return plantInsectValue(p).score>=70}).length,profiled:plants.filter(function(p){return plantInsectValue(p).source==="Artprofil"}).length,native:native}}''','score model')
sub(r'function bloomGapRecommendation\(g\)\{[^\n]*\}',r'''function bloomGapRecommendation(g){var gaps=[];for(var m=3;m<=10;m++)if(!g.counts[m-1])gaps.push(m);if(gaps.length){var names=gaps.map(function(m){return MONTHS[m-1]});if(gaps.some(function(m){return m<=4}))return"Was jetzt am meisten bringt: mehr Frühblüher für "+names.filter(function(x,i){return gaps[i]<=4}).join(", ")+".";if(gaps.some(function(m){return m>=9}))return"Was jetzt am meisten bringt: mehr Spätblüher für "+names.filter(function(x,i){return gaps[i]>=9}).join(", ")+".";return"Blühlücke: In "+names.join(", ")+" fehlt derzeit eine eingetragene Blühpflanze."}if(g.habitat<8){var cats=new Set(state.habitats.filter(function(h){return h.status==="present"||h.status==="optimized"}).map(function(h){return habitatLibraryItem(h.type).category}));if(!cats.has("structure"))return"Was jetzt am meisten bringt: Nist- oder Strukturraum ergänzen, z. B. offene Bodenstelle, Totholz oder Sandarium.";if(!cats.has("water"))return"Was jetzt am meisten bringt: eine sichere Wasserstelle ergänzen.";return"Zusätzliche Lebensraum-Strukturen würden den Garten weiter aufwerten."}if(g.practice<6)return"Das Blühangebot und die Lebensräume sind gut. Naturnahe Pflege – besonders Winterstängel, Laub und wenig Nachtlicht – bietet noch Potenzial.";return"Sehr ausgewogen: Nahrung, Lebensräume und naturnahe Pflege greifen gut ineinander. Beobachtete Tiere zeigen zusätzlich, wer den Garten tatsächlich nutzt."}''','recommendation')

