sub(r'function load\(\)\{[^\n]*\}\nfunction loadSync',r'''function load(){try{var raw=localStorage.getItem(STORE);if(raw){var d=JSON.parse(raw);state.plz=d.plz||"";state.loc=d.loc||null;state.gardenCenter=d.gardenCenter||null;state.plants=(Array.isArray(d.plants)?d.plants:[]).map(normalizePlantData);state.habitats=(Array.isArray(d.habitats)?d.habitats:[]).map(normalizeHabitatEntry);state.animals=(Array.isArray(d.animals)?d.animals:[]).map(normalizeAnimalObservation);state.zones=Array.isArray(d.zones)?d.zones:[];state.ecology=normalizeEcology(d.ecology);if(!Array.isArray(d.habitats))migrateLegacyHabitats(d.ecology);state.settings=Object.assign({plantnetKey:DEFAULT_PLANTNET_KEY,seasonMode:"auto",animations:true,mapView:null,onboardingDismissed:false,plantView:"collection",plantSort:"name",natureTab:"plants"},d.settings||{});if(!(state.settings.plantnetKey||"").trim())state.settings.plantnetKey=DEFAULT_PLANTNET_KEY;if(!["auto","spring","summer","autumn","winter"].includes(state.settings.seasonMode))state.settings.seasonMode="auto";if(!["plants","habitats","animals"].includes(state.settings.natureTab))state.settings.natureTab="plants";if(state.settings.animations!==false)state.settings.animations=true;state.days=[7,14,30,60,90].includes(Number(d.days))?Number(d.days):30}else{var old=localStorage.getItem("giess_plz");if(old)state.plz=old}}catch(e){console.warn(e)}loadSync()}
function loadSync''','load',re.S)
sub(r'function cloudPayload\(\)\{[^\n]*\}', 'function cloudPayload(){return{version:3,plz:state.plz||"",loc:state.loc||null,gardenCenter:state.gardenCenter||null,plants:state.plants||[],habitats:state.habitats||[],animals:state.animals||[],zones:state.zones||[],ecology:state.ecology||normalizeEcology(null)}}','cloud payload')
sub(r'function save\(\)\{[^\n]*\}', 'function save(){try{localStorage.setItem(STORE,JSON.stringify({plz:state.plz,loc:state.loc,gardenCenter:state.gardenCenter,plants:state.plants,habitats:state.habitats,animals:state.animals,zones:state.zones,ecology:state.ecology,settings:state.settings,days:state.days}));if(syncState.enabled&&!syncState.applying){var ph=cloudPayloadHash();if(ph&&ph!==syncState.lastPayloadHash){syncState.dirty=true;saveSync();scheduleCloudPush()}}return true}catch(e){globalError("Lokaler Speicher ist voll. Exportiere ein Backup und lösche gegebenenfalls alte Fotos.");return false}}','save')
sub(r'function applyCloudPayload\(p\)\{[^\n]*\}', 'function applyCloudPayload(p){p=p||{};syncState.applying=true;state.plz=p.plz||"";state.loc=p.loc||null;state.gardenCenter=p.gardenCenter||null;state.plants=(Array.isArray(p.plants)?p.plants:[]).map(normalizePlantData);state.habitats=(Array.isArray(p.habitats)?p.habitats:[]).map(normalizeHabitatEntry);state.animals=(Array.isArray(p.animals)?p.animals:[]).map(normalizeAnimalObservation);state.zones=Array.isArray(p.zones)?p.zones:[];state.ecology=normalizeEcology(p.ecology);save();syncState.applying=false;renderAll();if(state.plz)refreshWeather(false)}','apply cloud')

