sub(r'function renderEcoDashboard\(\)\{[^\n]*\}',r'''function renderEcoDashboard(){var g=gardenEcoScore(),score=el("ecoGardenScore"),level=el("ecoGardenLevel"),summary=el("ecoGardenSummary"),stats=el("ecoGardenStats"),bars=el("ecoBloomBars"),labels=el("ecoBloomLabels"),rec=el("ecoRecommendation");if(!score)return;var any=state.plants.length||state.habitats.length;if(!any){score.innerHTML='– <small>/ 100</small>';level.textContent="🐝 Noch keine Bewertung";summary.textContent="Lege Pflanzen und Lebensräume an. Tierbeobachtungen dokumentieren später, wer deinen Garten tatsächlich nutzt.";stats.innerHTML='<span class="eco-stat">0 Pflanzen</span><span class="eco-stat">0 Lebensräume</span>';rec.textContent="Mit der ersten Pflanzen- oder Lebensraumkarte startet die Bewertung."}else{var basis=(state.plants.length>=10||state.habitats.length>=4)?"gute Datengrundlage":(state.plants.length>=5||state.habitats.length>=2)?"mittlere Datengrundlage":"vorläufig";score.innerHTML=g.total+' <small>/ 100</small>';level.textContent="🐝 "+gardenEcoLevel(g.total)+" · "+basis;summary.textContent="Orientierungswert aus Pflanzenqualität, Blühabdeckung, Vielfalt, Lebensräumen und naturnaher Pflege.";stats.innerHTML='<span class="eco-stat">'+g.valuable+' wertvolle Pflanzen</span><span class="eco-stat">'+state.habitats.length+' Lebensräume</span><span class="eco-stat">'+state.animals.length+' Tierbeobachtungen</span>';rec.textContent=bloomGapRecommendation(g)}var breakdown=el("ecoScoreBreakdown");if(!breakdown){breakdown=document.createElement("div");breakdown.id="ecoScoreBreakdown";breakdown.className="score-breakdown";rec.parentNode.insertBefore(breakdown,rec)}breakdown.innerHTML='<div class="score-part"><b>'+g.quality+'/40</b><small>Pflanzen</small></div><div class="score-part"><b>'+g.bloom+'/20</b><small>Blüte</small></div><div class="score-part"><b>'+g.diversity+'/15</b><small>Vielfalt</small></div><div class="score-part"><b>'+g.habitat+'/15</b><small>Lebensräume</small></div><div class="score-part"><b>'+g.practice+'/10</b><small>Pflege</small></div>';bars.innerHTML=g.counts.map(function(n){return'<span class="'+(n>=2?'good':n===1?'some':'')+'" title="'+n+' blühende '+(n===1?'Art':'Arten')+'"></span>'}).join("");labels.innerHTML=MONTHS.map(function(m){return'<span>'+m.slice(0,1)+'</span>'}).join("");renderPracticeSettings(g)}''','eco dashboard')

